namespace {

constexpr int kSampleRate = 8000;
constexpr int kDuration = 180;
constexpr double kBpm = 160;
constexpr double kOrigin = 0.1;
const auto kRate = mixxx::audio::SampleRate(kSampleRate);

enum class RhythmChange {
    KickPattern,
    OffbeatKicks,
    EntirePatternPhase,
    SmoothTempo,
    PercussionWithSyncopatedSubBass,
};

double beatTime(double beat, RhythmChange change) {
    const double base = kOrigin + beat * 60 / kBpm;
    if (change == RhythmChange::SmoothTempo) {
        // A six-percent period increase over the full recording.
        return base + 0.03 * (base - kOrigin) * (base - kOrigin) / kDuration;
    }
    return base + (change == RhythmChange::EntirePatternPhase && base >= 90 ? 30 / kBpm : 0);
}

struct Instrument {
    std::vector<double> times;
    double low;
    double high;
    double decay;
    double level;
};

void feedBreakbeat(mixxx::BeatGridEvidence* evidence, RhythmChange change, double delay = 0) {
    std::array<Instrument, 4> drums{
            {{{}, 65, 240, 45, 0.7},
                    {{}, 1400, 2100, 100, 0.55},
                    {{}, 2700, 3300, 180, 0.22},
                    {{}, 45, 65, 25, 0.4}}};
    if (change == RhythmChange::PercussionWithSyncopatedSubBass) {
        drums[0] = {{}, 180, 240, 70, 0.85};
    }
    // Kicks occupy alternating quarters, snares the intervening backbeats,
    // and hi-hats mark eighths. Only the kick arrangement changes midway;
    // its new offbeat position must not move the independently steady clock.
    for (double beat = 0; beatTime(beat, change) < kDuration; beat += 0.5) {
        const auto eighth = static_cast<int>(std::lround(beat * 2));
        double kickBeat = beat;
        if (change == RhythmChange::PercussionWithSyncopatedSubBass && eighth % 2 == 0) {
            drums[0].times.push_back(beatTime(beat, change));
            drums[3].times.push_back(beatTime(beat + 0.5, change));
        } else if (change != RhythmChange::PercussionWithSyncopatedSubBass && eighth % 4 == 0) {
            if (change == RhythmChange::OffbeatKicks ||
                    (change == RhythmChange::KickPattern && beatTime(beat, change) >= 90)) {
                kickBeat += 0.5;
            }
            drums[0].times.push_back(beatTime(kickBeat, change));
        }
        if (eighth % 4 == 2) {
            drums[1].times.push_back(beatTime(beat, change));
        }
        drums[2].times.push_back(beatTime(beat, change));
    }
    for (auto& drum : drums) {
        for (auto& time : drum.times) {
            time += delay;
        }
    }
    std::array<size_t, drums.size()> next{};
    std::vector<CSAMPLE> stereo(8192);
    for (int start = 0; start < kSampleRate * kDuration; start += 4096) {
        const int frames = std::min(4096, kSampleRate * kDuration - start);
        for (int frame = 0; frame < frames; ++frame) {
            const double time = (start + frame) / static_cast<double>(kSampleRate);
            double value = 0;
            for (size_t instrument = 0; instrument < drums.size(); ++instrument) {
                const auto& drum = drums[instrument];
                while (next[instrument] < drum.times.size() &&
                        drum.times[next[instrument]] <= time) {
                    ++next[instrument];
                }
                if (next[instrument] == 0) {
                    continue;
                }
                const double elapsed = time - drum.times[next[instrument] - 1];
                if (elapsed < 0.15) {
                    value += drum.level * std::exp(-drum.decay * elapsed) *
                            (0.8 * std::cos(2 * M_PI * drum.low * elapsed) +
                                    0.2 * std::cos(2 * M_PI * drum.high * elapsed));
                }
            }
            stereo[frame * 2] = stereo[frame * 2 + 1] = static_cast<CSAMPLE>(value);
        }
        ASSERT_TRUE(evidence->processSamples(stereo.data(), frames * 2));
    }
    evidence->prepare();
}

mixxx::BeatsPointer constantGrid() {
    return mixxx::Beats::fromConstTempo(
            kRate, mixxx::audio::FramePos(kOrigin * kSampleRate), mixxx::Bpm(kBpm));
}

} // namespace

TEST(BreakbeatGridEvidenceTest, KickArrangementChangesKeepTheSteadySnareAndHatClock) {
    mixxx::BeatGridEvidence evidence;
    evidence.initialize(kRate);
    feedBreakbeat(&evidence, RhythmChange::KickPattern);
    const auto result = evidence.evaluate(constantGrid(), true);
    ASSERT_TRUE(result.reliable);
    ASSERT_TRUE(result.grid);
    EXPECT_FALSE(result.phaseChanges);
    EXPECT_TRUE(result.grid->hasConstantTempo());
    for (const double beat : {80.0, 320.0}) {
        const auto expected = mixxx::audio::FramePos((kOrigin + beat * 60 / kBpm) * kSampleRate);
        EXPECT_NEAR(expected.value(),
                result.grid->findClosestBeat(expected).value(),
                0.015 * kSampleRate);
    }
}

TEST(BreakbeatGridEvidenceTest, MetricalSwitchesDoNotOverrideAStableBreakbeatClock) {
    mixxx::BeatGridEvidence evidence;
    evidence.initialize(kRate);
    feedBreakbeat(&evidence, RhythmChange::KickPattern);
    QVector<mixxx::audio::FramePos> switched;
    for (double time = kOrigin; time < kDuration;
            time += 60 / (time < 90 ? kBpm / 2 : kBpm * 2 / 3)) {
        switched.push_back(mixxx::audio::FramePos(time * kSampleRate));
    }
    const auto constant = evidence.evaluate(constantGrid(), true);
    const auto variable = evidence.evaluate(mixxx::Beats::fromBeatPositions(kRate, switched), true);
    EXPECT_TRUE(mixxx::BeatGridEvidence::preferConstant(constant, variable, false));
}

