TEST(BreakbeatGridEvidenceTest, GenuineSmoothTempoDriftRetainsTheVariableClock) {
    mixxx::BeatGridEvidence evidence;
    evidence.initialize(kRate);
    feedBreakbeat(&evidence, RhythmChange::SmoothTempo);
    QVector<mixxx::audio::FramePos> positions;
    for (double beat = 0; beatTime(beat, RhythmChange::SmoothTempo) < kDuration; beat += 1) {
        positions.push_back(
                mixxx::audio::FramePos(beatTime(beat, RhythmChange::SmoothTempo) * kSampleRate));
    }
    const auto constant = evidence.evaluate(constantGrid(), true);
    const auto variable =
            evidence.evaluate(mixxx::Beats::fromBeatPositions(kRate, positions), true);
    EXPECT_FALSE(mixxx::BeatGridEvidence::preferConstant(constant, variable, true));
}

TEST(BreakbeatGridEvidenceTest, SteadyHalfTempoDoesNotAutomaticallyLoseToDoubleTempo) {
    mixxx::BeatGridEvidence evidence;
    evidence.initialize(kRate);
    std::vector<CSAMPLE> stereo(8192);
    constexpr double period = 120 / kBpm;
    for (int start = 0; start < kSampleRate * kDuration; start += 4096) {
        const int frames = std::min(4096, kSampleRate * kDuration - start);
        for (int frame = 0; frame < frames; ++frame) {
            const double time = (start + frame) / static_cast<double>(kSampleRate);
            const double elapsed = std::fmod(std::max(0.0, time - kOrigin), period);
            const auto value = static_cast<CSAMPLE>(time >= kOrigin && elapsed < 0.15
                            ? 0.8 * std::exp(-40 * elapsed) * std::cos(2 * M_PI * 65 * elapsed)
                            : 0);
            stereo[2 * frame] = stereo[2 * frame + 1] = value;
        }
        ASSERT_TRUE(evidence.processSamples(stereo.data(), frames * 2));
    }
    evidence.prepare();
    QVector<mixxx::audio::FramePos> positions;
    for (double time = kOrigin; time < kDuration; time += period) {
        positions.push_back(mixxx::audio::FramePos(time * kSampleRate));
    }
    const auto faster = evidence.evaluate(constantGrid(), true);
    const auto slower = evidence.evaluate(mixxx::Beats::fromBeatPositions(kRate, positions), true);
    ASSERT_TRUE(faster.reliable);
    ASSERT_TRUE(slower.reliable);
    EXPECT_FALSE(slower.unstableDensity);
    EXPECT_FALSE(mixxx::BeatGridEvidence::preferConstant(faster, slower, true));
}
